async function testUrl(url){
  return new Promise(resolve=>{
    const img = new Image();
    const t = setTimeout(()=>resolve({url, status:'timeout'}), 4000);
    img.onload = ()=>{clearTimeout(t); resolve({url, w:img.naturalWidth, h:img.naturalHeight})};
    img.onerror = ()=>{clearTimeout(t); resolve({url, status:'error'})};
    img.src = url;
  });
}
