const iframes = Array.from(document.querySelectorAll('iframe'));
let patched = [];
iframes.forEach((f,idx)=>{
  try {
    const w = f.contentWindow;
    if(w && !w.__patched){
      const orig = w.open;
      w.__openCalls = [];
      w.open = function(...args){ w.__openCalls.push(args); return orig.apply(w,args); };
      w.__patched = true;
      patched.push(idx);
    }
  } catch(e) { patched.push('err:'+e.message); }
});
JSON.stringify({iframeCount: iframes.length, patched});

const iframes = Array.from(document.querySelectorAll('iframe'));
const results = iframes.map((f,idx)=>{
  try { return {idx, calls: f.contentWindow.__openCalls}; } catch(e){ return {idx, err: e.message}; }
});
JSON.stringify({top: window.__openCalls, iframes: results});

